const XLSX = require('xlsx');
const wb = XLSX.readFile('D:/project_cc/beijian/beijian.xlsx');
const ws1 = wb.Sheets['发货项目清单(含BBOM SN)'];
const data1 = XLSX.utils.sheet_to_json(ws1, {header: 1, defval: ''});
const headers1 = data1[0];
const colIdx1 = {};
headers1.forEach((h, i) => { colIdx1[h] = i; });

// Convert Excel serial dates to readable dates
function serialToDate(serial) {
  if (typeof serial !== 'number') return serial;
  // Excel serial date: day 1 = 1900-01-01 (but with the Lotus 123 leap year bug)
  const epoch = new Date(1899, 11, 30);
  const d = new Date(epoch.getTime() + serial * 86400000);
  return d.toISOString().split('T')[0] + ' ' + d.toTimeString().split(' ')[0];
}

const dateCols = ['项目实施时间', '与泛联售前确认起保日期', '项目维保截止日', '部件购买时间'];
console.log('=== Date Column Analysis with Date Conversion ===\n');
dateCols.forEach(col => {
  const idx = colIdx1[col];
  const vals = data1.slice(1).map(r => r[idx]).filter(v => v !== '' && v !== undefined && v !== null);
  const uniqueSerials = [...new Set(vals)].sort((a,b) => a-b);

  console.log(col + ':');
  console.log('  Total non-empty values: ' + vals.length);
  console.log('  Empty/null values: ' + (data1.length - 1 - vals.length));
  console.log('  Unique serial numbers: ' + uniqueSerials.length);
  console.log('  Sample date range:');
  if (uniqueSerials.length > 0) {
    console.log('    Earliest serial: ' + uniqueSerials[0] + ' => ' + serialToDate(uniqueSerials[0]));
    console.log('    Latest serial:   ' + uniqueSerials[uniqueSerials.length-1] + ' => ' + serialToDate(uniqueSerials[uniqueSerials.length-1]));
    console.log('  First 10 unique values (converted):');
    uniqueSerials.slice(0, 10).forEach(s => console.log('    ' + s + ' => ' + serialToDate(s)));
  }
  console.log('');
});
