  const v = data1[r][isSpareIdx] || '(empty)';
  spareCounts[v] = (spareCounts[v] || 0) + 1;
}
console.log('\n是否备件 breakdown:');
Object.entries(spareCounts).forEach(([k,v]) => console.log('  ' + k + ': ' + v + ' (' + (v/totalData*100).toFixed(1) + '%)'));

